return ['domain'=>'lcfdev-tweaks','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'es_ES','project-id-version'=>'Tweaks 1.0.0','pot-creation-date'=>'2026-11-11T10:22:22+00:00','po-revision-date'=>'2026-11-11 00:00+0000','x-generator'=>'WP-CLI 2.11.0','messages'=>['https://github.com/cortesfrau/lcfdev-tweaks'=>'https://github.com/cortesfrau/lcfdev-tweaks','Lluis Cortes'=>'Lluis Cortes','https://github.com/cortesfrau'=>'https://github.com/cortesfrau','Tweaks'=>'Tweaks','Off'=>'Desactivado','Everywhere'=>'En todas partes','All visitors'=>'Todos los visitantes','Visitors who are not logged in'=>'Visitantes sin sesión iniciada','Cleanup'=>'Limpieza','Performance'=>'Rendimiento','Security'=>'Seguridad','Disable Dashicons'=>'Desactivar Dashicons','Stops loading the Dashicons stylesheet on the frontend unless something depends on it, such as the admin bar.'=>'Deja de cargar la hoja de estilos de Dashicons en el frontend, salvo que algo dependa de ella, como la barra de administración.','Disable Emojis'=>'Desactivar emojis','Generic login errors'=>'Errores de acceso genéricos','The login form shows the same error whether the username exists or not, and the lost password form never says that an account does not exist.'=>'El formulario de acceso muestra el mismo error tanto si el usuario existe como si no, y el formulario de contraseña olvidada nunca indica que una cuenta no existe.','<strong>Error:</strong> The username or password you entered is incorrect.'=>'<strong>Error:</strong> El nombre de usuario o la contraseña que has introducido no son correctos.','Block user enumeration'=>'Bloquear la enumeración de usuarios','Sorry, you are not allowed to list users.'=>'Lo siento, no tienes permisos para ver la lista de usuarios.','Disable XML-RPC'=>'Desactivar XML-RPC','Removes every XML-RPC method, pingbacks included, and the X-Pingback header. Jetpack and some older apps need XML-RPC.'=>'Elimina todos los métodos de XML-RPC, incluidos los pingbacks, y la cabecera X-Pingback. Jetpack y algunas aplicaciones antiguas necesitan XML-RPC.','Stops loading the emoji script and styles on the frontend and keeps emojis as plain text in feeds.'=>'Deja de cargar el script y los estilos de los emojis en el frontend y mantiene los emojis como texto en los feeds.','Hides usernames from visitors who are not logged in: ?author=N returns a 404, the REST users endpoint requires login, the users sitemap is removed and the oEmbed author link points to the home page. Author archives are not affected.'=>'Oculta los nombres de usuario a los visitantes sin sesión iniciada: ?author=N devuelve un 404, el endpoint REST de usuarios requiere iniciar sesión, se elimina el sitemap de usuarios y el enlace al autor de oEmbed apunta a la portada. Los archivos de autor no se ven afectados.','A lightweight plugin to disable WordPress features your site does not need, improving performance and hardening security through configurable settings.'=>'Un plugin ligero para desactivar funciones de WordPress que tu sitio no necesita, mejorando el rendimiento y reforzando la seguridad mediante ajustes configurables.']];